from collections import deque

def find_connected_components(grid):
    """Find all connected components of 8s (8-direction)"""
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 8 and not visited[r][c]:
                component = []
                queue = deque([(r, c)])
                visited[r][c] = True
                while queue:
                    cr, cc = queue.popleft()
                    component.append((cr, cc))
                    for dr, dc in [-1, 0, 1]:
                        for dc2 in [-1, 0, 1]:
                            if dr == 0 and dc2 == 0:
                                continue
                            nr, nc = cr + dr, cc + dc2
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if grid[nr][nc] == 8 and not visited[nr][nc]:
                                    visited[nr][nc] = True
                                    queue.append((nr, nc))
                components.append(component)

    return components

